function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(25);

  doStart({margin : 0.1, preset : 1});
}

function draw() {

  noFill();
  stroke(0, 80);
  strokeWeight(1);
  let nextGeneration = [];
  let removeGeneration = [];

  let currentGenerationCount = 0;
  //let ids = "";
  for (let key in currentGeneration) {
    let b = currentGeneration[key];

    currentGenerationCount++;

    let drawn = b.draw(drawingMode);

    if (drawn) drawnCount++;

    let current = b.subdivide();

    if (current != undefined) {
      if (current.length > 0) {
        nextGeneration = nextGeneration.concat(current);
      }
      removeGeneration.push(b.id);
    }
  }



  for (let key in removeGeneration) {
    let removeKey = removeGeneration[key];
    delete currentGeneration[removeKey];

  }

  for (let key in nextGeneration) {
    currentGeneration[nextGeneration[key].id] = nextGeneration[key];
  }

  let txt = "";
  txt = drawnCount + (drawnCount <= 1 ? " element has " : " elements have ") + "been drawn.";
  if (currentGenerationCount == 0 && nextGeneration.length == 0 && intervallListeners.length == 0) { // && drawnCount <= 5) {
    txt += " Drawing is finished. Click to restart.";
  }


  if (doDrawInfo) {
    drawInfo(width * boxMargin, height * (1 - boxMargin * 0.9), txt);
  }

}

