}


function DBox(data) {
  if (typeof DBox.sId == 'undefined') {
    DBox.sId = 0;
  }

  if ('x' in data && 'y' in data && 'w' in data && 'h' in data && 'r' in data) {
    for (let key in data) {
      this[key] = data[key];
    }

    if (this.w < 0.9) {
      this.w = 0.9;
    }

    if (this.h < 0.9) {
      this.h = 0.9;
    }
  } else {
    throw "Error. Wrong box data format"
  }

  this.id = DBox.sId++;
  this.drawn = false;
  this.rotationDir = random(100) < 50 ? -1 : 1;


  this.subdivide = function() {
    let children = [];
    let dice = random(100);

    if (this.h < 1 || this.w < 1 || dice < 1) {

      dice = random(100);
      if (this.h > 3 && this.w > 3) {
        if (dice < 30) {
          this.stipesInARectX(random(5, 50), random(PI / 10, PI - PI / 10));
        } else if (dice < 60) {
          this.stipesInARectY(random(5, 50), random(PI / 10, PI - PI / 10));
        } else if (dice < 75) {
          let sw = random(0.5, 2);
          this.pointsInARect(sw, random(6, 30), random(1));

        }
      } else if (dice < 50) {
        fill(10);
        this.draw();
        noFill();
      }
      return children;
    } else if (dice < 6) {

      dice = random(100);
      let treshold = random(this.h / this.w * 50);
      treshold = lerp(treshold, 50, ratioVal);

      let cut = random(1);
      let newR = this.r + random(boxRotation) * this.rotationDir;

      let c1, c2;

      let padd = random(100) < noPaddProb ? 0 : random(minPadd, maxPadd);

      if (dice < treshold) { // horizontal

        c1 = new DBox({
          x: this.x + padd,
          y: this.y + padd,
          w: this.w - padd * 2,
          h: this.h * cut - padd * 2,
          r: newR

        });
        c2 = new DBox({
          x: this.x + padd,
          y: this.y + this.h * cut + padd,
          w: this.w - padd * 2,
          h: this.h - this.h * cut - padd * 2,
          r: newR
        });
      } else { // vertical

        c1 = new DBox({
          x: this.x + padd,
          y: this.y + padd,
          w: this.w * cut - padd * 2,
          h: this.h - padd * 2,
          r: newR
        });
        c2 = new DBox({
          x: this.x + padd + this.w * cut,
          y: this.y + padd,
          w: this.w - this.w * cut - padd * 2,
          h: this.h - padd * 2,
          r: newR
        });
      }

      c1.rotationDir = this.rotationDir;
      c2.rotationDir = this.rotationDir * -1;

      if (c1.w > 3 && c1.h > 3) children.push(c1);
      if (c2.w > 3 && c2.h > 3) children.push(c2);


      if (drawingMode < 2 && this.r == 0 && padd > 0 && random(100) < filledContoursProb && c1.w > 3 && c1.h > 3 && c2.w > 3 && c2.h > 3) {
        noStroke();
        fill(0, random(20, 255));
        this.drawContour(c1, c2);
        stroke(10, 80);
        noFill();
      }

      return children;
    } else {
      return undefined;
    }
  }



  this.pointsInARect = function(sw, steps, offset) {


    let savePoints = [];

    let columns = parseInt(this.w / steps);
    let rows = parseInt(this.h / steps);

    if (columns < 1) {
      columns = 1;
    }

    if (rows < 1) {
      rows = 1;
    }

    let paddX = (this.w - steps * (columns - 1)) * 0.5;
    let paddY = (this.h - steps * (rows - 1)) * 0.5;


    if (paddX < 0) {
      paddX = 0.5 * this.w;
    }

    if (paddY < 0) {
      paddY = 0.5 * this.h;
    }

    for (let j = 0; j < rows; j++) {
      let yy = paddY + this.y + j * steps;

      for (let i = 0; i < (j % 2 == 1 ? columns + 1 : columns); i++) {
        let xx = paddX + this.x + i * steps;

        if (j % 2 == 1) {
          xx -= steps * offset;
        }

        if (xx < this.x + 0.5 || xx > this.x + this.w - 0.5) {
          continue;
        }
        savePoints.push(new DPoint({
          x: xx,
          y: yy
        }));
      }
    }

    let intervallListenerIndex = intervallListeners.length;
    let intervalListener = setInterval(function() {
      try {
        stroke(10);
        strokeWeight(sw);
        savePoints[0].draw();
        savePoints.splice(0, 1);
        strokeWeight(1);
        stroke(10, 80);
      } catch (e) {
        console.log(e);
      }

      if (savePoints.length == 0) {
        clearInterval(intervalListener);
        intervallListeners.clear(intervallListenerIndex);
      }
    }, 1);

    intervallListeners.push(intervalListener);
  }

  this.stipesInARectY = function(steps, angle) {

    let saveLines = [];
    let stripeCount = parseInt(this.h / steps);

    angle = constrain(angle, PI / 10, PI - PI / 10);
    stripeCount = stripeCount < 1 ? 1 : stripeCount;

    let fillH = abs(this.w / tan(angle)) + steps * 0.5;
    let addCount = parseInt(fillH / steps);

    let north = new DLine({
      startX: this.x,
      startY: this.y,
      endX: this.x + this.w,
      endY: this.y

    });

    let south = new DLine({
      startX: this.x,
      startY: this.y + this.h,
      endX: this.x + this.w,
      endY: this.y + this.h
    });

    let current = new DLine({
      start: new p5.Vector(0, 0),
      end: new p5.Vector(0, 0)
    });


    for (let i = 0; i < stripeCount + addCount; i++) {
      let startY = this.y + i * steps + steps * 0.5;

      if (this.w / tan(angle) > 0) {
        startY -= addCount * steps;
      }

      let startX = this.x;

      let endY = startY + this.w / tan(angle);
      let endX = this.x + this.w;

      if (startY < this.y || startY > this.y + this.h || endY > this.y + this.h || endY < this.y) {
        current.set({
          startX: startX,
          startY: startY,
          endX: endX,
          endY: endY

        });
        let crossNorth = current.getCross(north);
        if (crossNorth != undefined) {
          if (this.w / tan(angle) > 0) {
            startX = crossNorth.x;
            startY = crossNorth.y;
          } else {
            endX = crossNorth.x;
            endY = crossNorth.y;
          }
        }

        let crossSouth = current.getCross(south);
        if (crossSouth != null) {
          if (this.w / tan(angle) > 0) {
            endX = crossSouth.x;
            endY = crossSouth.y;
          } else {
            startX = crossSouth.x;
            startY = crossSouth.y;
          }
        }
      }

      startY = constrain(startY, this.y, this.y + this.h);
      endY = constrain(endY, this.y, this.y + this.h);

      saveLines.push(new DLine({
        startX: startX,
        startY: startY,
        endX: endX,
        endY: endY
      }));
    }

    let intervallListenerIndex = intervallListeners.length;
    let intervalListener = setInterval(function() {
      saveLines[0].draw();
      saveLines.splice(0, 1);

      if (saveLines.length == 0) {
        clearInterval(intervalListener);
        intervallListeners.clear(intervallListenerIndex);
      }
    }, 2);

    intervallListeners.push(intervalListener);
  }


  this.stipesInARectX = function(steps, angle) {
    let saveLines = [];
    let stripeCount = parseInt(this.w / steps);

    angle = constrain(angle, PI / 10, PI - PI / 10);
    stripeCount = stripeCount < 1 ? 1 : stripeCount;

    let fillW = abs(this.h / tan(angle)) + steps * 0.5;
    let addCount = parseInt(fillW / steps);

    let west = new DLine({
      startX: this.x,
      startY: this.y,
      endX: this.x,
      endY: this.y + this.h
    });

    let east = new DLine({
      startX: this.x + this.w,
      startY: this.y,
      endX: this.x + this.w,
      endY: this.y + this.h
    });

    let current = new DLine({
      start: new p5.Vector(0, 0),
      end: new p5.Vector(0, 0)
    });

    for (let i = 0; i < stripeCount + addCount; i++) {
      let startX = this.x + i * steps + steps * 0.5;

      if (this.h / tan(angle) > 0) {
        startX -= addCount * steps;
      }

      let startY = this.y;

      let endX = startX + this.h / tan(angle);
      let endY = this.y + this.h;

      if (startX < this.x || startX > this.x + this.w || endX > this.x + this.w || endX < this.x) {
        current.set({
          startX: startX,
          startY: startY,
          endX: endX,
          endY: endY
        });
        let crossWest = current.getCross(west);
        if (crossWest != undefined) {
          if (this.h / tan(angle) > 0) {
            startX = crossWest.x;
            startY = crossWest.y;
          } else {
            endX = crossWest.x;
            endY = crossWest.y;
          }
        }

        let crossEast = current.getCross(east);
        if (crossEast != undefined) {
          if (this.h / tan(angle) > 0) {
            endX = crossEast.x;
            endY = crossEast.y;
          } else {
            startX = crossEast.x;
            startY = crossEast.y;
          }
        }
      }

      startX = constrain(startX, this.x, this.x + this.w);
      endX = constrain(endX, this.x, this.x + this.w);

      saveLines.push(new DLine({
        startX: startX,
        startY: startY,
        endX: endX,
        endY: endY
      }));
    }

    let intervallListenerIndex = intervallListeners.length;
    let intervalListener = setInterval(function() {
      saveLines[0].draw();
      saveLines.splice(0, 1);

      if (saveLines.length == 0) {
        clearInterval(intervalListener);
        intervallListeners.clear(intervallListenerIndex);
      }
    }, 2);

    intervallListeners.push(intervalListener);
  }

  this.getPoint = function(originalPoint, rotationPoint) {
    let angle = this.r + atan2(-rotationPoint.y + originalPoint.y, -rotationPoint.x + originalPoint.x);
    let rad = dist(rotationPoint.x, rotationPoint.y, originalPoint.x, originalPoint.y);
    return {
      x: rotationPoint.x + cos(angle) * rad,
      y: rotationPoint.y + sin(angle) * rad
    };
  }

  this.drawContour = function(c1, c2) {

    beginShape();
    vertex(this.x, this.y);
    vertex(this.x + this.w, this.y);
    vertex(this.x + this.w, this.y + this.h);
    vertex(this.x, this.y + this.h);

    beginContour();
    vertex(c1.x, c1.y + c1.h);
    vertex(c1.x + c1.w, c1.y + c1.h);
    vertex(c1.x + c1.w, c1.y);
    vertex(c1.x, c1.y);
    endContour();

    beginContour();
    vertex(c2.x, c2.y + c2.h);
    vertex(c2.x + c2.w, c2.y + c2.h);
    vertex(c2.x + c2.w, c2.y);
    vertex(c2.x, c2.y);
    endContour();
    endShape(CLOSE);

  }

  this.draw = function(mode) {

    let didDraw = false;
    mode = mode || 0;

    if (mode == 4) {
      mode = parseInt(random(4));
    }

    if (!this.drawn) {
      didDraw = true;
      let center = {
        x: mode == 0 || mode == 2 ? width * 0.5 : this.x + this.w * 0.5,
        y: mode == 0 || mode == 2 ? height * 0.5 : this.y + this.h * 0.5
      };

      let points = [
        this.getPoint({
          x: this.x,
          y: this.y
        }, center),
        this.getPoint({
          x: this.x + this.w,
          y: this.y
        }, center),
        this.getPoint({
          x: this.x + this.w,
          y: this.y + this.h
        }, center),
        this.getPoint({
          x: this.x,
          y: this.y + this.h
        }, center)
      ];

      if (mode == 0 || mode == 1) {
        beginShape();
        for (let i in points) {
          vertex(points[i].x, points[i].y)
        }
        endShape(CLOSE);
      } else {
        points.push(points[0]);
        points.push(points[1]);
        points.push(points[2]);

        beginShape();
        for (let i in points) {
          curveVertex(points[i].x, points[i].y)
        }
        endShape();
      }
      this.drawn = true;

    }

    return didDraw;
  }

}

function DLine(data) {
  if ('start' in data && 'end' in data) {
    this.start = data.start;
    this.end = data.end;
  } else if ('startX' in data && 'startY' in data && 'endX' in data && 'endY' in data) {
    this.start = new p5.Vector(data.startX, data.startY);
    this.end = new p5.Vector(data.endX, data.endY);
  } else throw "Error. Wrong line data format";

  this.set = function(data) {
    if ('startX' in data && 'startY' in data && 'endX' in data && 'endY' in data) {
      this.start.x = data.startX;
      this.start.y = data.startY;
      this.end.x = data.endX;
      this.end.y = data.endY;
    } else throw "Error. Wrong data format";
  }

  this.getLength = function() {
    return this.start.dist(this.end);
  }

  this.draw = function() {
    line(this.start.x, this.start.y, this.end.x, this.end.y);
  }


  this.getNormal = function() {
    return new p5.Vector(this.end.x - this.start.x, this.end.y - this.start.y);
  }

  this.getAngle = function() {
    return atan2(this.end.y - this.start.y, this.end.x - this.start.x);
  }

  this.getDirection = function() {
    let angle = this.getAngle();
    return new p5.Vector(cos(angle), sin(angle));
  }

  this.getCross = function(dline) {
    let start1 = this.start;
    let dir1 = this.getDirection();
    let l1 = this.getLength();

    let start2 = dline.start;
    let dir2 = dline.getDirection();
    let l2 = dline.getLength();

    let skalar2 = (start2.y * dir1.x - start1.y * dir1.x - dir1.y * start2.x + start1.x * dir1.y) / (dir2.x * dir1.y - dir2.y * dir1.x);
    let skalar1 = (start2.x + skalar2 * dir2.x - start1.x) / dir1.x;

    if (skalar1 < 0 || skalar2 < 0) {
      //println("no cross");
      return undefined;
    }

    let crossed1 = new p5.Vector(dir1.x, dir1.y);
    crossed1.mult(skalar1);
    crossed1.add(start1);

    let crossed2 = new p5.Vector(dir2.x, dir2.y);
    crossed2.mult(skalar2);
    crossed2.add(start2);

    if (crossed1.dist(start1) > l1 || crossed2.dist(start2) > l2) {
      //println("cross out of line");
      return undefined;
    } else {
      //println("succesfull cross");
      return crossed1;
    }
  }

