    // line(-normal.y, normal.x, normal.y, -normal.x);
    let normal = new DLine(normalCopy.x + lerp(this.start.x, this.end.x, 0.5), normalCopy.y + lerp(this.start.y, this.end.y, 0.5), lerp(this.start.x, this.end.x, 0.5), lerp(this.start.y, this.end.y, 0.5));
